module top_module(ALUControl, A, B, shamt, ALUResult, zero);input [3:0] ALUControl;
    input [31:0] A, B;
    input [4:0] shamt;
    output reg [31:0] ALUResult;
    output zero;
    always @(*)
      case (ALUControl)
        0: ALUResult <= A & B;
        1: ALUResult <= A | B;
        2: ALUResult <= A + B;
        3: ALUResult <= B << shamt;
        4: ALUResult <= A & ~B;
        5: ALUResult <= A | ~B;
        6: ALUResult <= A - B;
        7: ALUResult <= (A < B) ? 1 : 0;
        8: ALUResult <= B >> shamt; 
        9: ALUResult <= B >>> shamt;
        default: ALUResult <= 0; 
