module top_module(
    input		  	 mclk,
	input		  	 rst_n,
	input	   [2:0] key,
	output reg [2:0] key_en
    );parameter DURATION = 50_000;                           
	reg [15:0] cnt; 

	wire ken_enable;
	assign ken_enable = key[2] | key[1] | key[0]; 

	always @(posedge mclk or negedge rst_n)
	begin
		if(!rst_n)
			cnt <= 11'd0;
		else if(ken_enable == 1) begin
			if(cnt == DURATION)
				cnt <= cnt;
			else 
				cnt <= cnt + 1'b1;
			end
		else
			cnt <= 16'b0;
	end

	always @(posedge mclk or negedge rst_n) 
	begin
		if(!rst_n) key_en <= 3'd0;
		else if(key[0]) key_en[0] <= (cnt == DURATION-1'b1) ? 1'b1 : 1'b0;
		else if(key[1]) key_en[1] <= (cnt == DURATION-1'b1) ? 1'b1 : 1'b0;
		else if(key[2]) key_en[2] <= (cnt == DURATION-1'b1) ? 1'b1 : 1'b0;
		else key_en <= key_en;
	end


endmodule

