reg [1:0] amount_inserted; // total amount of money inserted so far

always @(posedge clk) begin
    if (reset) begin
        amount_inserted <= 0;
        dispenser1 <= 0;
        dispenser2 <= 0;
        dispenser3 <= 0;
        dispenser4 <= 0;
        change <= 2'b00;
    end else begin
        amount_inserted <= amount_inserted + coin_value[coin];
        if (amount_inserted >= product_price) begin
            case (dispense)
                2'b00: dispenser1 <= 1;
                2'b01: dispenser2 <= 1;
                2'b10: dispenser3 <= 1;
                2'b11: dispenser4 <= 1;
            endcase
            change <= amount_inserted - product_price;
            amount_inserted <= 0;
        end else if (amount_inserted > 0) begin
            change <= amount_inserted;
            amount_inserted <= 0;
        end
    end
end

endmodule

