module bcd_counter(
    input wire clk,
    input wire rst,
    output reg [7:0] count
);

    always @(posedge clk) begin
        if (rst) begin
            count <= 8'b00000000;
        end else if (count == 8'b10011001) begin
            count <= 8'b00000000;
        end else if (count[3:0] == 4'b1001) begin
            count[7:4] <= count[7:4] + 1;
            count[3:0] <= 4'b0000;
        end else begin
            count[3:0] <= count[3:0] + 1;
        end
    end
endmodule

