            count <= 0;  
            out_clk <= 0;  
        end  

        else if (count == 250000) 
		begin  
			count <= 0;  
			out_clk <= ~out_clk;  
		end
		else begin  
			count <= count+1;  
			out_clk <= out_clk;  
		end  
    end  

endmodule

