                  // If subsig1 is 0 and subsig2 is 1, set subout to 0
                  (subsig1 == 0 && subsig2 == 1) ? 0 :
                  // If both subsig1 and subsig2 are 1, set subout to 0
                  (subsig1 == 1 && subsig2 == 1) ? 0 :
                  // If both subsig1 and subsig2 are 0, set subout to 1
                  1;
endmodule

