module top_module(
    input wire sclk,
    input wire reset,
    input wire [7:0] s_data,
    input wire s_valid,
    output wire s_ready,
    output wire [7:0] m_data,
    output wire m_valid,
    input wire m_ready
);// states
    localparam IDLE = 2'b00;
    localparam SEND = 2'b01;
    localparam WAIT = 2'b10;

    // state register
    reg [1:0] state, next_state;

    // data register
    reg [7:0] data_reg;

    // output registers
    reg m_valid_reg;
    reg s_ready_reg;

    // combinational logic
    assign s_ready = s_ready_reg;
    assign m_data = data_reg;
    assign m_valid = m_valid_reg;

    // state machine
    always @(posedge sclk, posedge reset) begin
        if (reset) begin
            state <= IDLE;
            m_valid_reg <= 1'b0;
            s_ready_reg <= 1'b0;
        end else begin
            state <= next_state;
            m_valid_reg <= (state == SEND);
            s_ready_reg <= (state == IDLE);
        end
    end

    // next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (s_valid && s_ready) begin
                    next_state = SEND;
                    data_reg <= s_data;
                end else begin
                    next_state = IDLE;
                end
            end
            SEND: begin
                if (m_ready) begin
                    next_state = WAIT;
                end else begin
                    next_state = SEND;
                end
            end
            WAIT: begin
                if (m_ready) begin
                    next_state = SEND;
                    data_reg <= s_data;
                end else begin
                    next_state = WAIT;
                end
            end
        endcase
    end

endmodule

