module top_module(
  input clk,
  input reset,
  input data,
  output reg match
);reg [1:0] state;
parameter S0 = 2'b00;
parameter S1 = 2'b01;

always @(posedge clk) begin
  if (reset) begin
    state <= S0;
    match <= 0;
  end else begin
    case (state)
      S0: begin
        if (data == 1'b1)
          state <= S1;
        else
          state <= S0;
      end
      S1: begin
        if (data == 1'b0)
          state <= S0;
        else if (match)
          state <= S1;
        else
          begin
            match <= 1;
            state <= S1;
          end
      end
    endcase
  end
end

endmodule

