module top_module(
    input clk,
    input reset,
    output reg green,
    output reg yellow,
    output reg red
);// Define states
    parameter GREEN = 2'b00;
    parameter YELLOW = 2'b01;
    parameter RED = 2'b10;

    // Define state register
    reg [1:0] state;

    // Define state machine
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            state <= GREEN;
        end else begin
            case (state)
                GREEN: begin
                    green <= 1;
                    yellow <= 0;
                    red <= 0;
                    if (count == 10) begin
                        state <= YELLOW;
                        count <= 0;
                    end else begin
                        count <= count + 1;
                    end
                end
                YELLOW: begin
                    green <= 0;
                    yellow <= 1;
                    red <= 0;
                    if (count == 2) begin
                        state <= RED;
                        count <= 0;
                    end else begin
                        count <= count + 1;
                    end
                end
                RED: begin
                    green <= 0;
                    yellow <= 0;
                    red <= 1;
                    if (count == 10) begin
                        state <= GREEN;
                        count <= 0;
                    end else begin
                        count <= count + 1;
                    end
                end
            endcase
        end
    end

    // Define count register
    reg [3:0] count;

endmodule

