module shift_register(
    input       clk   ,
    input       load  ,
    input       [7:0] in   ,

    output reg  [7:0] out
);

    // 8-bit Shift Register with Parallel Load
    always @(posedge clk) begin
        if (load)
            out <= in;
        else
            out <= {out[6:0], 1'b0}; // Shift left
    end

endmodule

