      if(tx_trig_rst_n == 1'b0)
         tx_trig_reg <= 1'b1;
      else if(tx_trig_count == 8'hFF)
         tx_trig_reg <= 1'b0;

   assign tx_trig = tx_trig_reg;

endmodule

