module mealy_machine (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter A=0, B=1, C=2, D=3;

    always_comb begin
        case (state)
            A: next_state = in1 ? C : B;
            B: next_state = in2 ? D : A;
            C: next_state = in1 ? A : D;
            D: next_state = in2 ? B : C;
        endcase
    end

    always_comb begin
        case (state)
            A: out = 0;
            B: out = 1;
            C: out = 0;
            D: out = 1;
        endcase
    end

endmodule

module top_module(input clk, input reset, input in, output p, output reg l);reg [13-1:0] r;

	always @(posedge clk or posedge reset) begin
		if(reset) begin
			r <= 0;
			l <= 0;
		end else begin
			if(r == 4999) begin // to ensure r doesn't go beyond 5000
				r <= 5000;
			end else if(r) begin
				r <= r + 1'b1;
			end
			if(in) begin
				r <= 1;
				l <= 1;
			end
			if(p) begin
				r <= 0;
				l <= 0;
			end
		end
	end

	assign p = r == 5000;
endmodule

module top_module(
    input clk,
    input reset,
    input load,
    input [1:0] ena,
    input [99:0] data,
    output reg [31:0] q
);reg [99:0] rotated_data;
reg [31:0] adder_out;

always @(posedge clk) begin
    if (reset) begin
        rotated_data <= 0;
        adder_out <= 0;
    end else begin
        if (load) begin
            if (ena == 2'b00) begin
                rotated_data <= data;
            end else if (ena == 2'b01) begin
                rotated_data <= {data[31:0], data[99:32]};
            end else if (ena == 2'b10) begin
                rotated_data <= {data[67:0], data[99:68]};
            end else begin
                rotated_data <= {data[33:0], data[99:34]};
            end
        end

        adder_out <= rotated_data[31:0] + 32'd12345678;
        q <= adder_out;
    end
end

endmodule

