module top_module (
    input clk,
    input d,
    input set,
    input reset,
    output reg q
);

    // D flip-flop with synchronous set and reset logic
    always @(posedge clk) begin
        if (reset) begin
            q <= 0;
        end else if (set) begin
            q <= 1;
        end else begin
            q <= d;
        end
    end

endmodule

module gray_code_counter_2bit 
(
  input reset,
  input clk,
  input enable,

  output reg [1:0] count
);

  always @(posedge clk or posedge reset) begin
    if (reset) 
	begin
      count <= 2'b00;
    end 

	else if (enable) 
	begin
      case (count)
        2'b00: count <= 2'b01;
        2'b01: count <= 2'b11;
        2'b11: count <= 2'b10;
        2'b10: count <= 2'b00;
        default: count <= 2'b00;
      endcase
    end
  end

endmodule

